<section class="page-heading"><div><span class="eyebrow">PIPAS / PADRÓN</span><h1><?= e($title) ?></h1><p><?= ($_GET['route']??'')==='dotaciones'?'Administra cuotas regulares y autorizaciones adicionales.':'Consulta y da seguimiento a los expedientes de beneficiarios.' ?></p></div><?php if(can('create')):?><a class="button primary" href="<?= e(url('nuevo')) ?>"><?= icon('plus') ?> Nuevo beneficiario</a><?php endif;?></section>
<section class="card filter-card"><form class="search-form" method="get"><input type="hidden" name="route" value="<?= e($_GET['route']??'padron') ?>"><label>Buscar por<select name="by"><?php foreach(['nombre'=>'Nombre completo','folio'=>'Folio','curp'=>'CURP','recibo'=>'Número de recibo'] as $v=>$l):?><option value="<?= $v ?>" <?= ($_GET['by']??'nombre')===$v?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></label><label class="search-term">Dato del beneficiario<div class="input-icon"><?= icon('search') ?><input name="q" placeholder="Escribe para buscar…" value="<?= e($_GET['q']??'') ?>" maxlength="190"></div></label><label>Estado<select name="status"><option value="">Todos los estados</option><?php foreach(['1','2','3','0','4','5'] as $s):?><option value="<?= $s ?>" <?= ($_GET['status']??'')===$s?'selected':'' ?>><?= statusLabel($s) ?></option><?php endforeach;?></select></label><label>Colonia<select name="colonia"><option value="">Todas las colonias</option><?php foreach($catalogs['colonia'] as $c):?><option value="<?= $c['id'] ?>" <?= (string)($_GET['colonia']??'')===(string)$c['id']?'selected':'' ?>><?= e($c['nombre']) ?></option><?php endforeach;?></select></label><button class="button primary">Buscar</button><a class="icon-button clear-search" title="Limpiar búsqueda" aria-label="Limpiar búsqueda" href="<?= e(url($_GET['route']??'padron')) ?>">↺</a></form></section>
<section class="card"><header class="card-heading"><div class="inline-heading"><h2>Beneficiarios</h2><span class="count-pill"><?= number_format($result['total']) ?> registros</span></div><span class="muted small">Página <?= $result['page'] ?> de <?= $result['pages'] ?></span></header><?php if(!$result['rows']):?><div class="empty"><span class="empty-icon"><?= icon('search') ?></span><h3>No hay beneficiarios para mostrar</h3><p>Prueba con otros datos o registra un nuevo beneficiario.</p><a class="button secondary" href="<?= e(url($_GET['route']??'padron')) ?>">Limpiar filtros</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Folio / Beneficiario</th><th>Domicilio</th><th>Dotación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($result['rows'] as $r):?><tr><td><a class="person-link" href="<?= e(url('detalle',['id'=>$r['id_padron']])) ?>"><span class="folio"><?= e($r['folio']) ?></span><strong><?= e($r['nombre_completo']) ?></strong><small><?= e($r['curp']) ?></small></a></td><td><strong class="cell-title"><?= e($r['colonia_nombre']) ?></strong><small class="cell-subtitle"><?= e($r['calle'].' '.$r['num_ext_mza'].($r['num_int_lote']?' Int. '.$r['num_int_lote']:'')) ?></small></td><td><strong><?= e($r['dotacion']) ?> viajes</strong><small class="cell-subtitle"><?= money($r['tarifa']) ?> / viaje</small></td><td><?= badge($r['status_padron']) ?></td><td><div class="row-actions"><a class="button tiny secondary" href="<?= e(url('detalle',['id'=>$r['id_padron']])) ?>">Ver ficha <?= icon('arrow') ?></a><?php if(($_GET['route']??'')==='bloqueos' && in_array($r['status_padron'],['1','2'])):?><a class="text-link" href="<?= e(url('operacion',['id'=>$r['id_padron'],'action'=>$r['status_padron']==='1'?'bloquear':'reactivar'])) ?>"><?= $r['status_padron']==='1'?'Bloquear':'Reactivar' ?></a><?php elseif(($_GET['route']??'')==='dotaciones' && $r['status_padron']==='1'):?><a class="text-link" href="<?= e(url('operacion',['id'=>$r['id_padron'],'action'=>'dotacion'])) ?>">Cambiar dotación</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php if($result['pages']>1):?><nav class="pagination" aria-label="Paginación"><?php if($result['page']>1):?><a class="button secondary tiny" href="<?= e(url($_GET['route']??'padron',array_merge(array_diff_key($_GET,['route'=>1]),['page'=>$result['page']-1]))) ?>">Anterior</a><?php endif;?><span><?= $result['page'] ?> / <?= $result['pages'] ?></span><?php if($result['page']<$result['pages']):?><a class="button secondary tiny" href="<?= e(url($_GET['route']??'padron',array_merge(array_diff_key($_GET,['route'=>1]),['page'=>$result['page']+1]))) ?>">Siguiente</a><?php endif;?></nav><?php endif;?></section>
